package com.acme.core.common.security;

import com.acme.core.common.core.CurrentClock;
import com.acme.core.common.core.IdGenerator;
import com.acme.core.common.core.PlatformException;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.Base64;
import java.util.HexFormat;

/**
 * Lightweight HMAC token V1 (generated by engineering-platform 0.1.0).
 *
 * Payload: userId|issuedAtEpochSeconds|expiresAtEpochSeconds|tokenId
 * Signature: HMAC-SHA256(payload, secret)
 *
 * Binds userId / issuedAt / expiresAt (+ tokenId). Expired tokens are rejected.
 * No JWT library, no Spring Security framework, no distributed token store.
 */
public final class TokenService {

    private final String secret;
    private final long expirationSeconds;
    private final CurrentClock clock;
    private final IdGenerator idGenerator;

    public TokenService(String secret, long expirationSeconds, CurrentClock clock, IdGenerator idGenerator) {
        if (secret == null || secret.length() < 16) {
            throw new PlatformException(
                    com.acme.core.common.core.ErrorCode.of("TOKEN_SECRET_INVALID", "token secret must be configured"));
        }
        this.secret = secret;
        this.expirationSeconds = expirationSeconds;
        this.clock = clock;
        this.idGenerator = idGenerator;
    }

    /** Issue a token for the given user id. */
    public String issue(Long userId) {
        Instant now = clock.now();
        Instant expiresAt = now.plusSeconds(expirationSeconds);
        String payload = userId + "|" + now.getEpochSecond() + "|" + expiresAt.getEpochSecond()
                + "|" + idGenerator.nextId();
        String signature = hmac(payload);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(payload.getBytes(StandardCharsets.UTF_8))
                + "." + signature;
    }

    /**
     * Validate a token. Returns the user id when valid.
     *
     * @throws PlatformException with TOKEN_INVALID / TOKEN_EXPIRED when invalid.
     */
    public Long validate(String token) {
        if (token == null || token.isBlank()) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        String[] parts = token.split("\\.", 2);
        if (parts.length != 2) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        String payload;
        try {
            payload = new String(Base64.getUrlDecoder().decode(parts[0]), StandardCharsets.UTF_8);
        } catch (IllegalArgumentException e) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        String expected = hmac(payload);
        if (!constantTimeEquals(expected, parts[1])) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        String[] fields = payload.split("\\|", -1);
        if (fields.length < 3) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        long expiresAt;
        try {
            expiresAt = Long.parseLong(fields[2]);
        } catch (NumberFormatException e) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
        if (clock.now().getEpochSecond() >= expiresAt) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_EXPIRED);
        }
        try {
            return Long.valueOf(fields[0]);
        } catch (NumberFormatException e) {
            throw new PlatformException(SecurityErrorCodes.TOKEN_INVALID);
        }
    }

    private String hmac(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            return HexFormat.of().formatHex(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            throw new PlatformException(
                    com.acme.core.common.core.ErrorCode.of("TOKEN_HMAC_FAILED", "token signing unavailable"));
        }
    }

    private static boolean constantTimeEquals(String a, String b) {
        if (a == null || b == null || a.length() != b.length()) {
            return false;
        }
        int result = 0;
        for (int i = 0; i < a.length(); i++) {
            result |= a.charAt(i) ^ b.charAt(i);
        }
        return result == 0;
    }
}
